92  bool KAr::openArchive(QIODevice::OpenMode mode)
    93  {
    94      // Open archive
    95
    96      if (mode == QIODevice::WriteOnly) {
    97          return true;
    98      }
    99      if (mode != QIODevice::ReadOnly && mode != QIODevice::ReadWrite) {
   100          setErrorString(tr("Unsupported mode %1").arg(mode));
   101          return false;
   102      }
   103
   104      QIODevice *dev = device();
   105      if (!dev) {
   106          return false;
   107      }
   108
   109      QByteArray magic = dev->read(7);
   110      if (magic != "!<arch>") {
   111          setErrorString(tr("Invalid main magic"));
   112          return false;
   113      }
   114
   115      char *ar_longnames = nullptr;
   116      while (! dev->atEnd()) {
   117          QByteArray ar_header;
   118          ar_header.resize(60);
   119
   120          dev->seek(dev->pos() + (2 - (dev->pos() % 2)) % 2);   // Ar headers are padded to byte boundary
   121
   122          if (dev->read(ar_header.data(), 60) != 60) {   // Read ar header
   123              //qCWarning(KArchiveLog) << "Couldn't read header";
   124              delete[] ar_longnames;
   125              //return false;
   126              return true; // Probably EOF / trailing junk
   127          }
   128
   129          if (!ar_header.endsWith("`\n")) { // Check header magic // krazy:exclude=strings
   130              setErrorString(tr("Invalid magic"));
   131              delete[] ar_longnames;
   132              return false;
   133          }
   134
   135          QByteArray name = ar_header.mid(0, 16);   // Process header
   136          const int date = ar_header.mid(16, 12).trimmed().toInt();
   137          //const int uid = ar_header.mid( 28, 6 ).trimmed().toInt();
   138          //const int gid = ar_header.mid( 34, 6 ).trimmed().toInt();
   139          const int mode = ar_header.mid(40, 8).trimmed().toInt();
   140          const qint64 size = ar_header.mid(48, 10).trimmed().toInt();
   141
   142          bool skip_entry = false; // Deal with special entries
   143          if (name.mid(0, 1) == "/") {
   144              if (name.mid(1, 1) == "/") { // Longfilename table entry
   145                  delete[] ar_longnames;
   146                  ar_longnames = new char[size + 1];
   147                  ar_longnames[size] = '\0';
   148                  dev->read(ar_longnames, size);
   149                  skip_entry = true;
   150                  //qCDebug(KArchiveLog) << "Read in longnames entry";
   151              } else if (name.mid(1, 1) == " ") { // Symbol table entry
   152                  //qCDebug(KArchiveLog) << "Skipped symbol entry";
   153                  dev->seek(dev->pos() + size);
   154                  skip_entry = true;
   155              } else { // Longfilename
   156                  //qCDebug(KArchiveLog) << "Longfilename #" << name.mid(1, 15).toInt();
   157                  if (! ar_longnames) {
   158                      setErrorString(tr("Invalid longfilename reference"));
   159                      delete[] ar_longnames;
   160                      return false;
   161                  }
   162                  name = &ar_longnames[name.mid(1, 15).toInt()];
   163                  name = name.left(name.indexOf("/"));
   164              }
   165          }
